import { API, graphqlOperation } from "aws-amplify";
import { create_list_edit_bussinesstype } from "@/graphql/mutations.js";
export default {
  props: {
    createBusinessType: Boolean
  },
  data() {
    return {
      businessTypeName: "",
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.businessTypeName = "";
      if (this.$refs.form) {
        this.$refs.form.resetValidation();
        this.$refs.form.reset();
      }
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.add_mutation();
      }
    },
    async add_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_bussinesstype, {
          input: {
            action_type: "CREATE",
            bussinesstypes_name: this.businessTypeName
          }
        }));
        var response = JSON.parse(result.data.create_list_edit_bussinesstype);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.close_dialog();
        } else {
          this.$emit("errorMsg", response.Message || "Failed to add business type");
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors?.[0]?.message || "Error adding business type");
      }
    }
  }
};
